t('RATE-AF',[('RATE','RAte control Therapy Evaluation'),('AF','in permanent Atrial Fibrillation')],'Essai RATE-AF (2020)','<p>Digoxine contre bisoprolol chez des sujets âgés en FA permanente avec symptômes d’insuffisance cardiaque : qualité de vie comparable à 6 mois, moins d’effets indésirables sous digoxine.</p>','i48-d-dig')
t('CAST',[('C','Cardiac'),('A','Arrhythmia'),('S','Suppression'),('T','Trial')],'Essai CAST (1989)','<p>Flécaïnide et encaïnide après infarctus pour supprimer les extrasystoles ventriculaires : surmortalité. Origine de la contre-indication de la classe Ic dans la coronaropathie.</p>','i48-d-flec')
t('ATHENA',[('ATHENA','nom d’essai arrangé à partir de « A placebo-controlled, double-blind, parallel arm Trial to assess the efficacy of dronedarone for the prevention of cardiovascular Hospitalization or death from any cause in patiENts with Atrial fibrillation », non strictement lettre à lettre')],'Essai ATHENA (2009)','<p>Dronédarone : réduction des hospitalisations cardiovasculaires et des décès dans la FA non permanente.</p>','i48-d-drone')
t('PALLAS',[('PALLAS','nom d’essai arrangé à partir de « Permanent Atrial fibriLLAtion outcome Study using dronedarone on top of standard therapy », non strictement lettre à lettre')],'Essai PALLAS (2011)','<p>Dronédarone dans la FA permanente : excès de décès, d’AVC et d’insuffisance cardiaque ; essai arrêté.</p>','i48-d-drone')
t('ANDROMEDA',[('ANDROMEDA','nom d’essai arrangé à partir de « ANtiarrhythmic trial with DROnedarone in Moderate to severe congestive heart failure Evaluating morbidity DecreAse », non strictement lettre à lettre')],'Essai ANDROMEDA (2008)','<p>Dronédarone dans l’insuffisance cardiaque sévère récemment décompensée : surmortalité.</p>','i48-d-drone')
t('ANNEXA-I',[('ANNEXA','nom d’essai arrangé à partir de « ANdexanet alfa, a Novel Antidote to the anticoagulation Effects of factor Xa inhibitors »'),('I','Intracranial hemorrhage (hémorragie intracrânienne)')],'Essai ANNEXA-I (2024)','<p>Andexanet alfa contre soins usuels dans l’hémorragie intracérébrale sous inhibiteur du facteur Xa : meilleure hémostase, davantage d’événements thrombotiques dont des AVC ischémiques.</p>','i48-antidote')
t('AFFIRM',[('AFFIRM','nom d’essai arrangé à partir de « Atrial Fibrillation Follow-up Investigation of Rhythm Management », non strictement lettre à lettre')],'Essai AFFIRM (2002)','<p>Contrôle du rythme contre contrôle de la fréquence dans la FA de patients âgés à risque d’AVC : pas de différence de mortalité ; les AVC survenaient surtout après arrêt de l’anticoagulation ou sous INR infrathérapeutique.</p>','i48-cha')
t('AVERROES',[('AVERROES','nom d’essai arrangé à partir de « Apixaban VERsus acetylsalicylic acid to pRevent strOkE in atrial fibrillation patientS who have failed or are unsuitable for vitamin K antagonist treatment », non strictement lettre à lettre')],'Essai AVERROES (2011)','<p>Apixaban contre aspirine chez des patients en FA inéligibles à l’antivitamine K : réduction d’environ 55 % des AVC et embolies systémiques, sans excès significatif d’hémorragie majeure.</p>','i48-aod')
a('DIG',[('D','Digitalis'),('I','Investigation'),('G','Group')],'Essai DIG (1997)','<p>Digoxine contre placebo dans l’insuffisance cardiaque en rythme sinusal : mortalité inchangée, hospitalisations pour insuffisance cardiaque réduites.</p>','i48-d-dig')
